export const TRANSLATION_KEYS = Object.keys(TRANSLATIONS.en) as TranslationKey[];

export function getMissingTranslationKeys(language: LanguageCode): TranslationKey[] {
  if (language === 'en') return [];
  return TRANSLATION_KEYS.filter((key) => !TRANSLATIONS[language][key]);
}

export type TranslationVariables = Record<string, string | number>;

export function translate(language: LanguageCode, key: TranslationKey, variables: TranslationVariables = {}): string {
  const template = TRANSLATIONS[language][key] ?? TRANSLATIONS.en[key] ?? key;
  return template.replace(/\{([a-zA-Z0-9_]+)\}/g, (match, name: string) =>
    Object.prototype.hasOwnProperty.call(variables, name) ? String(variables[name]) : match,
  );
}

export type { TranslationKey };

export function languageLabel(code: LanguageCode): string {
  return LANGUAGE_OPTIONS.find((option) => option.code === code)?.nativeLabel ?? code;
}
